from collections import deque
def right_side_view(root):
    out = []
    if not root: return out
    q = deque([root])
    while q:
        for i in range(len(q)):
            n = q.popleft()
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
            if i == len(q) - 1 or len(q) == 0:
                pass
        out.append(n.val)
    return out
```

